#include <cuda_runtime.h>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
__global__ void Sobel(const unsigned char* in, unsigned char* out, int w, int h, int count) { int p=blockIdx.x*blockDim.x+threadIdx.x, total=w*h*count; if(p>=total)return; int x=p%w,y=(p/w)%h; if(x==0||y==0||x==w-1||y==h-1){out[p]=0;return;} int img=p/(w*h),base=img*w*h, gx=-in[base+(y-1)*w+x-1]-2*in[base+y*w+x-1]-in[base+(y+1)*w+x-1]+in[base+(y-1)*w+x+1]+2*in[base+y*w+x+1]+in[base+(y+1)*w+x+1]; int gy=-in[base+(y-1)*w+x-1]-2*in[base+(y-1)*w+x]-in[base+(y-1)*w+x+1]+in[base+(y+1)*w+x-1]+2*in[base+(y+1)*w+x]+in[base+(y+1)*w+x+1]; out[p]=(unsigned char)min(255,abs(gx)+abs(gy)); }
int main(int argc,char**argv){int n=256,w=1024,h=768;std::string out="proof/results.csv";for(int i=1;i+1<argc;++i){std::string a(argv[i]);if(a=="--images")n=std::stoi(argv[++i]);if(a=="--width")w=std::stoi(argv[++i]);if(a=="--height")h=std::stoi(argv[++i]);if(a=="--output")out=argv[++i];}size_t bytes=(size_t)n*w*h;std::vector<unsigned char> host(bytes),result(bytes);for(size_t i=0;i<bytes;++i)host[i]=(i*17+i/97)%256;unsigned char *di,*do_;cudaMalloc(&di,bytes);cudaMalloc(&do_,bytes);cudaMemcpy(di,host.data(),bytes,cudaMemcpyHostToDevice);cudaEvent_t s,e;cudaEventCreate(&s);cudaEventCreate(&e);cudaEventRecord(s);Sobel<<<(bytes+255)/256,256>>>(di,do_,w,h,n);cudaEventRecord(e);cudaEventSynchronize(e);float ms;cudaEventElapsedTime(&ms,s,e);cudaMemcpy(result.data(),do_,bytes,cudaMemcpyDeviceToHost);std::ofstream f(out);f<<"images,width,height,pixels,gpu_ms,mpix_per_sec\n"<<n<<","<<w<<","<<h<<","<<bytes<<","<<ms<<","<<(bytes/1e6)/(ms/1000)<<"\n";std::cout<<"Processed "<<n<<" images on CUDA in "<<ms<<" ms\nWrote "<<out<<"\n";cudaFree(di);cudaFree(do_);}
